export const protocolVersion = 1;

/**
 * Merge overlapping or touching number ranges [start, end].
 * @param {Array<number>[]} ranges Input ranges, where each is a [start, end] pair with start <= end.
 * @returns {Array<number>[]} Sorted merged ranges, empty if input is empty or invalid.
 * @throws {TypeError} if input contains invalid pairs, reversed endpoints, or nonfinite numbers.
 */
export function mergeRanges(ranges) {
  if (!Array.isArray(ranges)) {
    throw new TypeError("Input must be an array of ranges.");
  }
  if (ranges.length === 0) {
    return [];
  }

  // Sort ranges by start ascending, then by end ascending for consistency
  ranges = ranges.slice().sort((a, b) => a[0] - b[0] || a[1] - b[1]);

  const merged = [ranges[0].slice()];

  for (let i = 1; i < ranges.length; i++) {
    const [currentStart, currentEnd] = ranges[i];
    const lastStart = merged[merged.length - 1][0];
    const lastEnd = merged[merged.length - 1][1];

    // Check if ranges are reversed or have non-finite values
    if (!Number.isFinite(ranges[i][0]) || !Number.isFinite(ranges[i][1]) || ranges[i][0] > ranges[i][1]) {
      throw new TypeError("Ranges must have finite values and start <= end.");
    }

    if (currentStart <= lastEnd) {
      // Overlapping: merge them
      // Update the end to the maximum of the current and last end
      merged[merged.length - 1][1] = Math.max(lastEnd, currentEnd);
    } else {
      merged.push(ranges[i].slice());
    }
  }

  return merged;
}

